function isNumber(v) { return typeof v === 'number' && Number.isFinite(v); }

// Runs once for the WHOLE batch — one item per evaluable scanner_result
// arrives here from "Load Forward Candles". Must loop $input.all()
// explicitly (same bug pattern found and fixed across every multi-item
// Code node in this project — confirmed via live E2E testing).
// itemMatching(i) pairs each row back to the scanner_result that produced it.

const items = $input.all();
const out = [];

for (let i = 0; i < items.length; i++) {
  let original;
  try { original = $('Load Evaluable Scanner Results').itemMatching(i).json; } catch (e) { continue; }
  const row = items[i].json;
  const candles = Array.isArray(row.candles) ? row.candles : [];
  const estDays = original.target1_estimated_days;
  const target1 = original.target1;
  const invalidation = original.invalidation_price;

  if (!isNumber(estDays) || !isNumber(target1) || !isNumber(invalidation) || estDays < 1) {
    out.push({ json: { scannerResultId: original.scanner_result_id, _skip: true } });
    continue;
  }

  const windowCandles = candles.slice(0, estDays);
  let outcome = null;
  let resolvedDay = null;

  for (let d = 0; d < windowCandles.length; d++) {
    const c = windowCandles[d];
    const hitTarget = isNumber(c.high) && c.high >= target1;
    const hitStop = isNumber(c.low) && c.low <= invalidation;
    if (hitTarget || hitStop) {
      // Same-day ambiguity (both true on one daily bar) treated as a stop —
      // conservative, matches prediction_evaluation.success's convention.
      outcome = hitStop ? 'STOP_HIT' : 'TARGET1_HIT';
      resolvedDay = d + 1;
      break;
    }
  }

  if (!outcome) {
    if (windowCandles.length >= estDays) {
      outcome = 'EXPIRED_NO_HIT';
    } else {
      // Not enough future sessions yet to know either way — re-check later,
      // never guess early.
      out.push({ json: { scannerResultId: original.scanner_result_id, _skip: true } });
      continue;
    }
  }

  out.push({ json: {
    scannerResultId: original.scanner_result_id,
    targetEstimatedDays: estDays,
    outcome,
    resolvedDay,
    _skip: false,
  } });
}

return out;

const count = $input.first().json.evaluated_count;
return [{ json: {
  workflow: '16-egx-target-window-evaluation',
  finishedAt: new Date().toISOString(),
  totalEvaluatedRows: count,
} }];
